 public static class InstallResult extends BroadcastReceiver {
  @Override public void onReceive(Context context,Intent intent){int status=intent.getIntExtra(android.content.pm.PackageInstaller.EXTRA_STATUS,android.content.pm.PackageInstaller.STATUS_FAILURE);if(status==android.content.pm.PackageInstaller.STATUS_PENDING_USER_ACTION){Intent confirm=intent.getParcelableExtra(Intent.EXTRA_INTENT);if(confirm!=null){try{confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);context.startActivity(confirm);return;}catch(Exception ignored){}}}String msg=status==android.content.pm.PackageInstaller.STATUS_SUCCESS?"安装成功":status==android.content.pm.PackageInstaller.STATUS_PENDING_USER_ACTION?"无法打开系统确认界面，请使用浏览器下载安装":intent.getStringExtra(android.content.pm.PackageInstaller.EXTRA_STATUS_MESSAGE);ToastResult(context,msg==null?"安装未完成（"+status+"）":msg);}
  private static void ToastResult(Context c,String msg){android.widget.Toast.makeText(c,msg,android.widget.Toast.LENGTH_LONG).show();}
 }
 private void verifyUpdate(java.io.File f,int expected)throws Exception{android.content.pm.PackageManager pm=getPackageManager();int flags=android.content.pm.PackageManager.GET_SIGNATURES;android.content.pm.PackageInfo apk=pm.getPackageArchiveInfo(f.getAbsolutePath(),flags),own=pm.getPackageInfo(getPackageName(),flags);if(apk==null||!getPackageName().equals(apk.packageName)||apk.versionCode!=expected||apk.versionCode<=own.versionCode||apk.signatures==null||own.signatures==null||!new java.util.HashSet<>(java.util.Arrays.asList(apk.signatures)).equals(new java.util.HashSet<>(java.util.Arrays.asList(own.signatures))))throw new Exception("安装包版本或签名不匹配");}

 public class MotionBridge { @JavascriptInterface public void setEnabled(boolean enabled){runOnUiThread(()->{requested=enabled;updateMotion();});} }
 private void updateMotion(){if(sensors==null)return;boolean next=requested&&foreground&&accelerometer!=null;if(next==listening)return;if(next)listening=sensors.registerListener(this,accelerometer,SensorManager.SENSOR_DELAY_UI);else {sensors.unregisterListener(this);listening=false;}}
 @Override public void onResume(){super.onResume();foreground=true;updateMotion();getBridge().getWebView().evaluateJavascript("window.dispatchEvent(new Event('studyResume328'))",null);}
 @Override public void onPause(){foreground=false;updateMotion();super.onPause();}
 @Override public void onDestroy(){foreground=false;updateMotion();super.onDestroy();}
 @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
 @Override public void onSensorChanged(SensorEvent e){if(!listening)return;float x=e.values[0],y=e.values[1];if(!Float.isFinite(x)||!Float.isFinite(y))return;getBridge().getWebView().evaluateJavascript("window.studyMotionSample && window.studyMotionSample("+x+","+y+")",null);}


 public class HapticBridge {
  private long lastTick=0;
  @JavascriptInterface public void pulse(String kind,String strength){runOnUiThread(()->{
   if(!foreground)return;
   boolean tick="tick".equals(kind); long now=SystemClock.elapsedRealtime();
   if(tick && now-lastTick<45)return; if(tick)lastTick=now;
   // Do not interrupt the existing repeating completion alarm.
   if(TimerService.prefs(MainActivity.this).getBoolean("pendingDone",false))return;
   int duration=12, amplitude=130;
   switch(kind==null?"tap":kind){case "tick":duration=8;amplitude=85;break;case "nav":duration=14;break;case "confirm":duration=20;amplitude=170;break;case "start":duration=30;amplitude=220;break;case "reset":duration=24;amplitude=180;break;case "end":duration=16;amplitude=150;break;}
   float factor="轻柔".equals(strength)?0.45f:"增强".equals(strength)?1.5f:1.0f;
   try { Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE); if(v!=null&&v.hasVibrator()){
    int ms=Math.max(4,Math.round(duration*factor)); int amp=Math.max(1,Math.min(255,Math.round(amplitude*factor)));
    if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(ms,v.hasAmplitudeControl()?amp:VibrationEffect.DEFAULT_AMPLITUDE));else v.vibrate(ms);
   }else getBridge().getWebView().performHapticFeedback(android.view.HapticFeedbackConstants.VIRTUAL_KEY);
   }catch(Exception e){getBridge().getWebView().performHapticFeedback(android.view.HapticFeedbackConstants.VIRTUAL_KEY);}
  });}
 }
