  void feedback(boolean finish){if(!prefs(this).getBoolean("feedback",true)||prefs(this).getBoolean("pendingDone",false))return;try{Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v==null||!v.hasVibrator())return;String strength=prefs(this).getString("strength","增强");float factor="轻柔".equals(strength)?.45f:"增强".equals(strength)?1.5f:1f;int ms=Math.max(4,Math.round((finish?42:30)*factor));int amp=Math.min(255,Math.round(165*factor));if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(ms,v.hasAmplitudeControl()?amp:VibrationEffect.DEFAULT_AMPLITUDE));else v.vibrate(ms);}catch(Exception ignored){}}
